mapper.select:
SELECT tb_dictionary_item.id, tb_dictionary_item.type_id, tb_dictionary_item.name, tb_dictionary_item.`value`, tb_dictionary_item.sort, tb_dictionary_item.is_default, tb_dictionary_item.status, tb_dictionary_item.gmt_created, tb_dictionary_item.gmt_modified FROM tb_dictionary_type LEFT JOIN tb_dictionary_item ON tb_dictionary_item.type_id = tb_dictionary_type.id
and tb_dictionary_type.code = #{code}
and tb_dictionary_item.id not in ('1289822872575731144','1289822872575731032')
